<script setup>
import DeviceSelect from '../DeviceSelect.vue'
import { computed, reactive, ref, watch } from 'vue'
import { canGovernance as can } from '../../governance/permissions.js'
import { createClientId } from '../../clientId.js'
import { UiMessage } from '../../ui/feedback.js'
import { governanceCatalog, governanceRead, governanceWrite, governanceUpload } from '../../governance/api.js'
import { conflictMessage, label, recordBody, resultOptions, sameSignal, time, verificationPayload } from '../../governance/helpers.js'
const props = defineProps({ modelValue:Boolean, devices:{type:Array,default:()=>[]}, configs:{type:Object,default:()=>({})}, initial:{type:Object,default:()=>({})}, roundId:{type:String,default:''} })
const emit = defineEmits(['update:modelValue','saved','navigate'])
const form = reactive({}), observations=ref([]),activities=ref([]), loading=ref(false), saving=ref(false), error=ref(''), cursor=ref(''), file=ref(null)
const observationRange=ref([Date.now()-7*86400000,Date.now()+1])
const source = computed(()=>recordBody(props.initial))
const existing=computed(()=>source.value?.verificationMethod?source.value:null)
const selectedSignal = computed(()=>observations.value.find(row=>form.observationIds?.includes(row.id)))
const signalObservations = computed(()=>selectedSignal.value ? observations.value.filter(row=>sameSignal(selectedSignal.value,row)) : observations.value)
const published = kind => (props.configs[kind]||[]).map(recordBody).filter(row=>row.status==='PUBLISHED'||row.id===existing.value?.[{templates:'templateRevisionId','scene-presets':'scenePresetRevisionId','type-profiles':'typeProfileRevisionId'}[kind]])
const fields = computed(()=>[...new Map(['templates','scene-presets','type-profiles'].flatMap(kind=>[...(published(kind).find(row=>row.id===form[{templates:'templateRevisionId','scene-presets':'scenePresetRevisionId','type-profiles':'typeProfileRevisionId'}[kind]])?.fields||[]),...(published(kind).find(row=>row.id===form[{templates:'templateRevisionId','scene-presets':'scenePresetRevisionId','type-profiles':'typeProfileRevisionId'}[kind]])?.facilityQuestions||[])]).map(field=>[field.id,field])).values()].filter(field=>!['fieldResult','activityRelation','facilityStatus'].includes(field.id)))
let generation=0
watch(()=>props.modelValue, value=>{if(value){const row=source.value||{}; Object.assign(form,{deviceId:row.deviceId||'',componentId:row.componentId||'',alarmType:row.alarmType||'',originKind:row.originKind||'',signalKey:row.signalKey||'',templateRevisionId:row.templateRevisionId||'',scenePresetRevisionId:row.scenePresetRevisionId||'',typeProfileRevisionId:row.typeProfileRevisionId||'',observationIds:row.observationIds?.slice()||[],verificationMethod:existing.value?.verificationMethod||'',verifiedAt:existing.value?.verifiedAt??null,fieldResult:existing.value?.fieldResult||'',activityRelation:existing.value?.activityRelation||'',facilityStatus:existing.value?.fieldValues?.facilityStatus||'',fieldValues:{...(existing.value?.fieldValues||{})},activityIds:existing.value?.activityIds?.slice()||[],checkScope:existing.value?.checkScope||'',description:existing.value?.description||'',attachmentIds:existing.value?.attachmentIds?.slice()||[],correctionReason:'',idempotencyKey:createClientId()}); observationRange.value=[row.window?.start||Date.now()-7*86400000,row.window?.end||Date.now()+1];error.value='';observations.value=[];cursor.value='';file.value=null;void load()}else generation++})
async function load(more=false){const token=++generation;loading.value=true;error.value='';try{if(!form.deviceId) return; const value=await governanceRead('observations','','',{deviceIds:[form.deviceId],alarmId:source.value?.alarmId||'',start:observationRange.value?.[0],end:observationRange.value?.[1],limit:100,cursor:more?cursor.value:''});if(token!==generation)return; const activityValue=await governanceCatalog('activities',{deviceIds:[form.deviceId]});if(token!==generation)return;activities.value=(activityValue.items||[]).map(recordBody).filter(row=>row.actual&&row.status==='CONFIRMED');const rows=(value.items||[]).map(recordBody);observations.value=more?[...observations.value,...rows]:rows;cursor.value=value.nextCursor||'';if(form.observationIds.length)chooseEvents(form.observationIds)}catch(cause){if(token===generation)error.value=cause.message}finally{if(token===generation)loading.value=false}}
function deviceChanged(){form.observationIds=[];form.componentId='';form.alarmType='';form.originKind='';form.signalKey='';void load()}
function chooseEvents(ids){const row=observations.value.find(item=>ids.includes(item.id));if(row){for(const key of ['deviceId','componentId','alarmType','originKind','signalKey'])form[key]=row[key]||'';form.observationIds=ids.filter(id=>observations.value.some(item=>item.id===id&&sameSignal(item,row)))}}
const writePermission=computed(()=>existing.value?`${existing.value.status==='DRAFT'?'PATCH':'POST'} /api/v1/alarm-governance/verifications/:id${existing.value.status==='DRAFT'?'':'/corrections'}`:'POST /api/v1/alarm-governance/verifications')
async function save() {
  if (saving.value || !can(writePermission.value)) return
  saving.value = true; error.value = ''
  let created = null
  try {
    const payload = verificationPayload(form, observations.value)
    if (existing.value && existing.value.status !== 'DRAFT' && !form.correctionReason.trim()) throw new Error('请填写追加更正理由')
    created = await governanceWrite('verifications', existing.value?.id || '', existing.value && existing.value.status !== 'DRAFT' ? 'corrections' : '', { ...payload, expectedVersion:existing.value?.version || 0 }, existing.value?.status === 'DRAFT' ? 'PATCH' : 'POST')
    const row = recordBody(created)
    if (file.value) await governanceUpload('verifications', row.id, file.value, [form.deviceId], form.idempotencyKey + ':attachment')
    if (props.roundId && can('POST /api/v1/alarm-governance/rounds/:id/verification-links')) await governanceWrite('rounds', props.roundId, 'verification-links', { verificationId:row.id, verificationVersion:row.version, observationIds:payload.observationIds, reason:'本次现场核实与当前轮次关联，适用范围保持原事件成员', idempotencyKey:form.idempotencyKey + ':round-link' })
    UiMessage.success('现场核实已保存'); emit('saved', created); emit('update:modelValue', false)
  } catch (cause) {
    if (created) {
      // The durable field record remains usable after attachment/link failures.
      emit('saved', created)
      error.value = `现场核实已经保存；附件或轮次关联未完成：${conflictMessage(cause)}。请关闭后在独立核实记录中继续。`
      file.value = null
    } else error.value = conflictMessage(cause)
  } finally { saving.value = false }
}
</script>
<template>
<ui-dialog :model-value="modelValue" :title="existing?(existing.status==='DRAFT'?'编辑现场核实草稿':'追加现场核实更正'):'填写现场核实'" width="min(760px,94vw)" :close-on-click-modal="false" @update:model-value="emit('update:modelValue',$event)"><div class="gov-dialog-body"><ui-alert v-if="error" :title="error" type="error" :closable="false"/><p class="gov-meta">核实独立保存；建事项与重开由负责人另行决定。现场异常继续按原告警流程处置。</p><ui-form label-position="top" :disabled="saving"><div class="gov-grid"><ui-form-item label="点位设备" required><DeviceSelect v-model="form.deviceId" :disabled="!!source?.deviceId" @change="deviceChanged"/></ui-form-item><ui-form-item label="核实方式" required><ui-select v-model="form.verificationMethod"><ui-option v-for="code in ['ON_SITE','PHONE','DOCUMENT_REVIEW','UNVERIFIED']" :key="code" :value="code" :label="label(code)"/></ui-select></ui-form-item><ui-form-item label="实际核实时间"><ui-date-time v-model="form.verifiedAt" clearable/></ui-form-item></div><ui-form-item label="事件读取区间"><ui-date-range v-model="observationRange"/><ui-button text size="small" :loading="loading" @click="load()">读取本区间事件</ui-button></ui-form-item><ui-form-item label="具体核实事件（同一点位和信号）" required><ui-select v-model="form.observationIds" multiple filterable :loading="loading" @change="chooseEvents"><ui-option v-for="row in signalObservations" :key="row.id" :value="row.id" :label="`${time(row.eventAt)} · ${row.componentId||'设备'} · ${row.alarmType} · ${label(row.factKind)} · ${row.signalKey}`"/></ui-select><ui-button v-if="cursor" text size="small" @click="load(true)">加载更多事件</ui-button></ui-form-item><ui-empty v-if="form.deviceId&&!loading&&!observations.length" description="没有可追溯的逐次事件，无法以聚合次数代替核实范围。"/><div class="gov-grid"><ui-form-item v-for="kind in ['templates','scene-presets','type-profiles']" :key="kind" :label="{templates:'取证模板','scene-presets':'场景预设','type-profiles':'报警类型配置'}[kind]" required><ui-select v-model="form[{templates:'templateRevisionId','scene-presets':'scenePresetRevisionId','type-profiles':'typeProfileRevisionId'}[kind]]" :disabled="!!existing" filterable><ui-option v-for="row in published(kind)" :key="row.id" :value="row.id" :label="`${row.name} · 版本 ${row.revisionNumber}`"/></ui-select></ui-form-item><ui-form-item label="看到什么" required><ui-select v-model="form.fieldResult" placeholder="请选择；没有默认正常结论"><ui-option v-for="code in resultOptions(form.alarmType)" :key="code" :value="code" :label="label(code)"/></ui-select></ui-form-item><ui-form-item label="当时活动与报警关系" required><ui-select v-model="form.activityRelation" placeholder="请选择或保留未知"><ui-option v-for="code in ['UNKNOWN','SUSPECTED','RELATED','UNRELATED','DISPUTED','CONFIRMED_RELATED','CONFIRMED_UNRELATED']" :key="code" :value="code" :label="label(code)"/></ui-select></ui-form-item><ui-form-item label="关联设施状态" required><ui-select v-model="form.facilityStatus" placeholder="请选择或保留未知"><ui-option v-for="code in ['UNKNOWN','NORMAL','ABNORMAL','DISPUTED']" :key="code" :value="code" :label="label(code)"/></ui-select></ui-form-item></div><ui-collapse v-if="fields.length"><ui-collapse-item title="按固定配置补充检查范围与现场证据" name="fields"><div class="gov-grid"><ui-form-item v-for="field in fields" :key="field.id" :label="field.label" :required="field.required"><ui-select v-if="['select','single','multi','SINGLE_SELECT','MULTI_SELECT'].includes(field.control)" v-model="form.fieldValues[field.id]" :multiple="['multi','MULTI_SELECT'].includes(field.control)" clearable><ui-option v-for="option in field.options||[]" :key="option.code" :value="option.code" :label="option.label"/></ui-select><ui-date-time v-else-if="['time','TIME'].includes(field.control)" v-model="form.fieldValues[field.id]" clearable/><ui-input-number v-else-if="['number','NUMBER'].includes(field.control)" v-model="form.fieldValues[field.id]" :min="field.min" :max="field.max"/><ui-input v-else v-model="form.fieldValues[field.id]" placeholder="未核实可填写未知"/></ui-form-item></div></ui-collapse-item></ui-collapse><ui-form-item label="人工核对关联实际活动（可空，不自动认定相关）"><ui-select v-model="form.activityIds" multiple filterable clearable><ui-option v-for="row in activities" :key="row.id" :value="row.id" :label="`${row.description||row.activityType} · ${time(row.startAt)} ～ ${time(row.endAt)} · ${label(row.timeQuality)}`"/></ui-select><p class="gov-meta">时间重叠只提供候选线索。仍需人工选择具体活动，并填写已确认相关、不相关或未知。</p></ui-form-item><ui-form-item label="实际检查范围（确认核实必填）"><ui-input v-model="form.checkScope" placeholder="记录已检查点位、区域与未覆盖范围"/></ui-form-item><ui-form-item label="检查范围、现场活动与原始说明"><ui-input v-model="form.description" type="textarea" :rows="3" placeholder="记录未到场、补登记、时钟不确定及检查限制"/></ui-form-item><ui-form-item v-if="existing&&existing.status!=='DRAFT'" label="更正理由" required><ui-input v-model="form.correctionReason" type="textarea"/></ui-form-item><ui-form-item label="现场附件（选填）"><input type="file" accept="image/png,image/jpeg,image/webp,application/pdf" @change="file=$event.target.files?.[0]||null"/></ui-form-item></ui-form></div><template #footer><ui-button :disabled="saving" @click="emit('update:modelValue',false)">取消</ui-button><ui-button v-if="can(writePermission)" type="primary" :loading="saving" :disabled="!observations.length" @click="save">保存现场核实</ui-button></template></ui-dialog>
</template>
